import java.util.Comparator;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;

final class ShopLog {
    static String describe(Object value) {
        if (value == null) return "nothing";
        if (value instanceof String s) return "text " + s;
        if (value instanceof List<?> l) return "list of " + l.size();    // List<String> would not compile
        if (value instanceof Map<?, ?> m) return "map of " + m.size();
        return "other";
    }

    static String render(Map<?, ?> map) {                                 // keys and values are Object
        return map.entrySet().stream()
            .sorted(Comparator.comparing(e -> String.valueOf(e.getKey())))
            .map(e -> e.getKey() + "=" + (e.getValue() instanceof Map<?, ?> m ? render(m) : e.getValue()))
            .collect(Collectors.joining(", ", "{", "}"));
    }

    static int drain(List<?> crate) {     // not a raw List: checks stay on
        int n = crate.size();
        crate.clear();
        return n;
    }
}

kotlin.src:
fun describe(value: Any?): String = when (value) {
    null -> "nothing"
    is String -> "text $value"
    is List<*> -> "list of ${value.size}"       // List<String> would not compile
    is Map<*, *> -> "map of ${value.size}"
    else -> "other"
}

fun render(map: Map<*, *>): String =                // keys and values are Any?
    map.entries
        .sortedBy { it.key.toString() }
        .joinToString(", ", "{", "}") { (k, v) -> "$k=${if (v is Map<*, *>) render(v) else v}" }

fun drain(crate: MutableList<*>): Int {           // Kotlin has no raw types
    val n = crate.size
    crate.clear()
    return n
}

