interface Dispenser<out T : Fruit> { fun next(): T }
interface Bin<in T> { fun drop(item: T) }
class Box<T>(var item: T)

fun drill(d: Dispenser<*>, b: Bin<*>, x: Box<*>, l: MutableList<*>) {
    val f: Fruit = d.next()    // Dispenser<*> = Dispenser<out Fruit>: reads keep the bound
    // b.drop(...)             // Bin<*> = Bin<in Nothing>: nothing can be dropped in
    val i: Any? = x.item       // Box<*> reads as Box<out Any?> (and writes as Box<in Nothing>)
    l.clear()                  // MutableList<*>: members that take no element still work
}

